package org.pocketsurf.browser

import android.content.Context
import android.net.Uri
import android.util.Base64
import android.webkit.WebMessage
import android.webkit.WebMessagePort
import android.webkit.WebView
import org.json.JSONObject
import java.util.UUID

/** One acknowledged chunk in flight; no JS interface or arbitrary native file path. */
class GeneratedFileTransfer(private val context:Context,private val view:WebView,private val url:String,private val destination:Uri,private val name:String,private val mime:String,private val downloads:SurfDownloads,private val valid:()->Boolean,private val finished:(String)->Unit):AutoCloseable {
 private var output:java.io.OutputStream?=null;private var ports:Array<WebMessagePort>?=null;private var item:SurfDownload?=null;private var bytes=0L;private var ended=false;private var reported=0L;private var reportTime=0L
 fun start(){try{require(destination.scheme=="content");output=context.contentResolver.openOutputStream(destination,"w")?:error("Cannot open destination");item=downloads.generated(url,name,mime,destination);val channel=view.createWebMessageChannel();ports=channel;require(channel.size==2);val token=UUID.randomUUID().toString();channel[0].setWebMessageCallback(object:WebMessagePort.WebMessageCallback(){override fun onMessage(port:WebMessagePort,message:WebMessage){if(ended)return;try{require(valid()){"Source page changed"};require(!downloads.cancelled(item!!.id)){"Cancelled"};val o=JSONObject(message.data?:error("Empty download message"));if(o.has("error"))error(if(o.optString("error")=="limit")"Generated download exceeds 64 MB"else"Website could not provide the generated file");if(o.optBoolean("done")){output?.close();output=null;downloads.generatedProgress(item!!.id,bytes,true);ended=true;ports?.forEach{runCatching{it.close()}};finished("Download saved: $name");return};val encoded=o.getString("chunk");require(encoded.length<=90000){"Oversized download chunk"};val chunk=Base64.decode(encoded,Base64.DEFAULT);require(chunk.size<=65536&&bytes+chunk.size<=MAX_BYTES){"Generated download exceeds 64 MB"};output?.write(chunk);bytes+=chunk.size;val now=android.os.SystemClock.uptimeMillis();if(bytes-reported>=262144||now-reportTime>=250){downloads.generatedProgress(item!!.id,bytes);reported=bytes;reportTime=now};port.postMessage(WebMessage("next"))}catch(e:Exception){abort(when{e.message=="Generated download exceeds 64 MB"->"Generated file exceeds the 64 MB limit";e.message=="Source page changed"->"Source page changed; generate the file again";e is java.io.IOException->"Storage write failed; check free space and try again";else->"Generated download interrupted; generate it again on the website"})}}});val origin=PageIdentity.origin(view.url.orEmpty())?:error("Unknown source origin");view.evaluateJavascript(script(url,token)){if(!valid()||PageIdentity.origin(view.url.orEmpty())!=origin){abort("Source page changed")}else runCatching{view.postWebMessage(WebMessage(token,arrayOf(channel[1])),Uri.parse(origin))}.onFailure{abort("Generated file channel failed")}}}catch(_:Exception){abort("Generated file could not be saved")}}
 private fun abort(message:String){if(ended)return;ended=true;runCatching{output?.close()};output=null;ports?.forEach{runCatching{it.close()}};item?.let{downloads.generatedProgress(it.id,bytes,failed=true)};runCatching{android.provider.DocumentsContract.deleteDocument(context.contentResolver,destination)};finished(message)}
 override fun close(){abort("Generated download cancelled")}
 companion object {
  const val MAX_BYTES=64L*1024*1024
  fun script(url:String,token:String):String="""(()=>{const token=${JSONObject.quote(token)},url=${JSONObject.quote(url)};function receive(e){if(e.data!==token||!e.ports||!e.ports[0])return;window.removeEventListener('message',receive);const port=e.ports[0];let reader,part=new Uint8Array(),offset=0,busy=false,total=0;port.onmessage=async()=>{if(busy)return;busy=true;try{if(!reader){const response=await fetch(url);if(!response.ok)throw Error();reader=response.body.getReader();}if(offset>=part.length){const next=await reader.read();if(next.done){port.postMessage(JSON.stringify({done:true}));port.close();return;}part=next.value;offset=0;}const piece=part.subarray(offset,offset+32768);offset+=piece.length;total+=piece.length;if(total>67108864)throw Error('limit');port.postMessage(JSON.stringify({chunk:btoa(String.fromCharCode(...piece))}));}catch(error){try{await reader?.cancel();}catch(_){}port.postMessage(JSON.stringify({error:error.message==='limit'?'limit':'Generated download failed'}));port.close();}finally{busy=false}};port.onmessage();}window.addEventListener('message',receive);setTimeout(()=>window.removeEventListener('message',receive),10000);})()"""
 }
}
